import json,glob,re
for f in sorted(glob.glob('page-*.json')):
    d=json.load(open(f))
    for e in d['entries']:
        for rc in e.get('ref_check',[])+[r for n in e.get('nodes',[]) for r in n.get('ref_check',[])]:
            if rc['ref'].startswith('KLN'):
                print(f, rc['ref'], rc['status'], rc['note'][:220])
EOF

cd /home/sfmqrb/git/rishe/data/verification/sources/refs
python3 - <<'EOF'
t=open('BQT_v2_pages.txt',encoding='utf-8',errors='replace').read()
pages=t.split('\f')
for i in range(510,516):
    p=pages[i]
    for ln in p.split('\n'):
        if 'پهلوی' in ln or 'اوستا' in ln or 'ازیر' in ln or 'azer' in ln.lower():
            print(i,'|',ln.strip()[:250])
EOF

